DELETE FROM investment_product
WHERE id = #{id}
AND source_type = 'PERSONAL'
AND owner_user_id = #{userId}

mapper.select:
SELECT 
FROM investment_product
WHERE id = #{id}
AND source_type = 'PERSONAL'
