SELECT FROM investment_product
source_type = 'PERSONAL' AND owner_user_id = #{userId}
source_type = 'PUBLIC' AND owner_user_id IS NULL
AND status IN ('AVAILABLE', 'ON_SALE') AND (#{riskPreferenceJson} = '[]' OR risk_level IS NOT NULL) AND (#{investmentHorizonJson} = '[]' OR JSON_OVERLAPS(JSON_ARRAY(investment_horizon), #{investmentHorizonJson})) AND (#{liquidityNeedJson} = '[]' OR JSON_OVERLAPS(JSON_ARRAY(liquidity_type), #{liquidityNeedJson})) AND (#{productTypeJson} = '[]' OR JSON_OVERLAPS(JSON_ARRAY(product_type), #{productTypeJson})) AND (#{returnExpectationJson} = '[]' OR JSON_OVERLAPS(JSON_ARRAY(return_type), #{returnExpectationJson})) AND (#{customerProfileJson} = '[]' OR JSON_OVERLAPS(target_customer, #{customerProfileJson})) AND (#{restrictionJson} = '[]' OR NOT JSON_OVERLAPS(tags, #{restrictionJson}))
ORDER BY updated_at DESC LIMIT #{limit}
